// Level "Canvas": 8 × 8 cells of 10 mm inside the frame.
// Pen down when Me and It are in the same cell; it stays down until they are more
// than 1.5 cells apart, so a small drift of one hand does not break the line.

const N = 8, CELL = 10, X0 = 140, Y0 = 63;
const PEN_UP_DISTANCE = 1.5 * CELL;
const COLORS = {
  red:   { fill: "#e63946", tone: 330 },
  green: { fill: "#2a9d4b", tone: 523 },
  blue:  { fill: "#2f6fdf", tone: 784 },
};

const pixels = new Array(N * N).fill(null); // colour name per cell, null = empty
const marks = new Array(N * N).fill(null);  // the coloured square in the preview
let color = "red";
let erasing = false;
let penDown = false;

/** Cell index under a point, or -1 outside the canvas. */
function cellAt(p) {
  const col = Math.floor((p.x - X0) / CELL), row = Math.floor((p.y - Y0) / CELL);
  return col >= 0 && col < N && row >= 0 && row < N ? row * N + col : -1;
}

function setPixel(i, value) {
  if (i < 0 || pixels[i] === value) return;
  pixels[i] = value;
  marks[i]?.remove();
  marks[i] = null;
  if (value) {
    const x = X0 + ((i % N) + 0.5) * CELL, y = Y0 + (Math.floor(i / N) + 0.5) * CELL;
    marks[i] = panto.entity({ x, y, r: CELL / 2, color: COLORS[value].fill });
    sound.beep(COLORS[value].tone, 70, { volume: 0.15 });
  } else {
    sound.tick();
  }
}

async function chirp(from, to) {
  await sound.beep(from, 50, { volume: 0.15 });
  sound.beep(to, 70, { volume: 0.15 });
}

function updatePen() {
  const meCell = cellAt(me.position);
  if (!penDown && meCell >= 0 && meCell === cellAt(it.position)) {
    penDown = true;
    chirp(500, 800);
  } else if (penDown && (meCell < 0 || distance(me, it) > PEN_UP_DISTANCE)) {
    penDown = false;
    chirp(800, 500);
  }
  if (penDown) setPixel(meCell, erasing ? null : color);
}

// It reads: every new cell says its colour, a tick means empty
let itCell = -1;
it.onMove((p) => {
  updatePen();
  const i = cellAt(p);
  if (i === itCell) return;
  itCell = i;
  if (i < 0 || penDown) return;
  if (pixels[i]) speak(pixels[i], { interrupt: true });
  else sound.tick();
});

// Me draws: a quiet low click at each cell border while the pen is up
let meCell = -1;
me.onMove((p) => {
  updatePen();
  const i = cellAt(p);
  if (i === meCell) return;
  meCell = i;
  if (i >= 0 && !penDown) sound.beep(180, 20, { volume: 0.08 });
});

// --- voice commands --------------------------------------------------------

// speech recognition often hears "red" as "read"
const MISHEARD = { red: ["read"], green: [], blue: [] };

for (const name of Object.keys(COLORS)) {
  voice.intent(name, {
    examples: [name, ...MISHEARD[name], `paint ${name}`, `use ${name}`, `switch to ${name}`, `make it ${name}`],
    interim: false,
    onMatch: () => {
      color = name;
      erasing = false;
      speak(name, { interrupt: true });
    },
  });
}

voice.intent("erase", {
  examples: ["erase", "remove", "eraser", "delete colour", "rubber"],
  interim: false,
  onMatch: () => {
    erasing = true;
    speak("Erase", { interrupt: true });
  },
});

voice.intent("status", {
  examples: ["which colour", "what colour is it", "which mode", "what am I painting"],
  interim: false,
  onMatch: () => speak(erasing ? "Erasing" : `Painting ${color}`, { interrupt: true }),
});

// --- "recognize": trace every outline of the painted cells with a rail -------
// Inner outlines count too, e.g. the inside edge of a painted ring.

let outlineRails = [];

/** Direction of a grid edge: 0 right, 1 down, 2 left, 3 up. */
const direction = (dx, dy) => (dx > 0 ? 0 : dy > 0 ? 1 : dx < 0 ? 2 : 3);
/** At a corner shared by two outlines, prefer turning right, then straight, then left. */
const turnRank = (turn) => (turn === 1 ? 0 : turn === 0 ? 1 : turn === 3 ? 2 : 3);

/** Every closed outline of the painted cells, in grid coordinates. */
function paintedOutlines() {
  // the edges between a painted and an empty cell, walked clockwise around the paint
  const edges = [];
  const add = (x1, y1, x2, y2) => edges.push({ x1, y1, x2, y2, used: false, dir: direction(x2 - x1, y2 - y1) });
  const empty = (x, y) => x < 0 || y < 0 || x >= N || y >= N || pixels[y * N + x] === null;
  for (let y = 0; y < N; y++) {
    for (let x = 0; x < N; x++) {
      if (empty(x, y)) continue;
      if (empty(x, y - 1)) add(x, y, x + 1, y);
      if (empty(x + 1, y)) add(x + 1, y, x + 1, y + 1);
      if (empty(x, y + 1)) add(x + 1, y + 1, x, y + 1);
      if (empty(x - 1, y)) add(x, y + 1, x, y);
    }
  }
  const key = (x, y) => `${x},${y}`;
  const outgoing = new Map();
  edges.forEach((e, i) => {
    const k = key(e.x1, e.y1);
    if (!outgoing.has(k)) outgoing.set(k, []);
    outgoing.get(k).push(i);
  });

  const loops = [];
  for (const first of edges) {
    if (first.used) continue;
    const points = [{ x: first.x1, y: first.y1 }];
    let edge = first;
    let closed = false;
    while (edge && !edge.used) {
      edge.used = true;
      points.push({ x: edge.x2, y: edge.y2 });
      if (edge.x2 === first.x1 && edge.y2 === first.y1) {
        closed = true;
        break;
      }
      const from = edge;
      const next = (outgoing.get(key(edge.x2, edge.y2)) ?? []).filter((i) => !edges[i].used);
      next.sort((a, b) => turnRank((edges[a].dir - from.dir + 4) % 4) - turnRank((edges[b].dir - from.dir + 4) % 4));
      edge = edges[next[0]];
    }
    if (closed && points.length >= 5) loops.push(toRail(points));
  }
  return loops;
}

/** Corner points of a closed outline in mm (at most 7, the first repeated at the end). */
function toRail(closed) {
  const points = closed.slice(0, -1);
  const corners = points.filter((cur, i) => {
    const prev = points[(i + points.length - 1) % points.length], next = points[(i + 1) % points.length];
    return cur.x - prev.x !== next.x - cur.x || cur.y - prev.y !== next.y - cur.y;
  });
  let selected = corners.length ? corners : points;
  if (selected.length > 7) selected = Array.from({ length: 7 }, (_, i) => selected[Math.round((i * (selected.length - 1)) / 6)]);
  const mm = selected.map((p) => ({ x: X0 + p.x * CELL, y: Y0 + p.y * CELL }));
  return [...mm, { ...mm[0] }];
}

function recognize() {
  const outlines = paintedOutlines();
  if (!outlines.length) return speak("Nothing painted yet.", { interrupt: true });
  outlineRails.forEach((rail) => rail.remove());
  outlineRails = outlines.map((points, i) => panto.rail(points, { strength: 2, handles: "me", name: `Outline ${i + 1}` }));
  speak(outlines.length === 1 ? "1 outline." : `${outlines.length} outlines.`, { interrupt: true });
}

voice.intent("recognize", {
  examples: ["recognize", "recognize shapes", "trace contours", "trace the outlines"],
  interim: false,
  onMatch: recognize,
});

