    let closed = false;
    while (edge && !edge.used) {
      edge.used = true;
      points.push({ x: edge.x2, y: edge.y2 });
      if (edge.x2 === first.x1 && edge.y2 === first.y1) {
        closed = true;
        break;
      }
      const from = edge;
      const next = (outgoing.get(key(edge.x2, edge.y2)) ?? []).filter((i) => !edges[i].used);
      next.sort((a, b) => turnRank((edges[a].dir - from.dir + 4) % 4) - turnRank((edges[b].dir - from.dir + 4) % 4));
      edge = edges[next[0]];
    }
    if (closed && points.length >= 5) loops.push(toRail(points));
  }
  return loops;
}

/** Corner points of a closed outline in mm (at most 7, the first repeated at the end). */
function toRail(closed) {
  const points = closed.slice(0, -1);
  const corners = points.filter((cur, i) => {
    const prev = points[(i + points.length - 1) % points.length], next = points[(i + 1) % points.length];
    return cur.x - prev.x !== next.x - cur.x || cur.y - prev.y !== next.y - cur.y;
  });
  let selected = corners.length ? corners : points;
  if (selected.length > 7) selected = Array.from({ length: 7 }, (_, i) => selected[Math.round((i * (selected.length - 1)) / 6)]);
  const mm = selected.map((p) => ({ x: X0 + p.x * CELL, y: Y0 + p.y * CELL }));
  return [...mm, { ...mm[0] }];
}

function recognize() {
  const outlines = paintedOutlines();
  if (!outlines.length) return speak("Nothing painted yet.", { interrupt: true });
  outlineRails.forEach((rail) => rail.remove());
  outlineRails = outlines.map((points, i) => panto.rail(points, { strength: 2, handles: "me", name: `Outline ${i + 1}` }));
  speak(outlines.length === 1 ? "1 outline." : `${outlines.length} outlines.`, { interrupt: true });
}

voice.intent("recognize", {
  examples: ["recognize", "recognize shapes", "trace contours", "trace the outlines"],
  interim: false,
  onMatch: recognize,
});

// Level "Feelable shapes": draw freely with Me, then feel what you drew.
// Say "start drawing", move Me, then say "stop drawing". A $1 recognizer names the shape
// (circle, square or triangle) and one rail follows the path, so Me can trace it again.

const SHAPES = {
  circle: Array.from({ length: 65 }, (_, i) => ({ x: 0.5 + 0.42 * Math.cos((i * 2 * Math.PI) / 64), y: 0.5 + 0.42 * Math.sin((i * 2 * Math.PI) / 64) })),
  square: [{ x: 0.15, y: 0.15 }, { x: 0.85, y: 0.15 }, { x: 0.85, y: 0.85 }, { x: 0.15, y: 0.85 }, { x: 0.15, y: 0.15 }],
  triangle: [{ x: 0.5, y: 0.12 }, { x: 0.88, y: 0.82 }, { x: 0.12, y: 0.82 }, { x: 0.5, y: 0.12 }],
};
const MAX_SCORE = 0.22; // worse matches are a "freeform shape"

let drawing = false;
let stroke = [];
let rails = [];

const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);

/** n points spread evenly along the path. */
function resample(points, n = 64) {
  const p = points.map((q) => ({ ...q }));
  let length = 0;
  for (let i = 1; i < p.length; i++) length += dist(p[i - 1], p[i]);
  if (length < 1) return p;
  const step = length / (n - 1), out = [p[0]];
  let carry = 0;
  for (let i = 1; i < p.length && out.length < n; i++) {
    let a = p[i - 1], seg = dist(a, p[i]);
    while (seg > 0 && carry + seg >= step && out.length < n) {
      const t = (step - carry) / seg, q = { x: a.x + t * (p[i].x - a.x), y: a.y + t * (p[i].y - a.y) };
      out.push(q);
      a = q;
      seg = dist(a, p[i]);
      carry = 0;
    }
    carry += seg;
  }
  while (out.length < n) out.push({ ...p[p.length - 1] });
  return out;
}

/** Resampled, rotated to a common angle, scaled to size 1 and centred. */
function normalize(points) {
  const p = resample(points), first = p[0];
  const angle = Math.atan2(p.reduce((s, q) => s + q.y - first.y, 0), p.reduce((s, q) => s + q.x - first.x, 0));
  const c = Math.cos(-angle), s = Math.sin(-angle);
  let r = p.map((q) => ({ x: q.x * c - q.y * s, y: q.x * s + q.y * c }));
  const xs = r.map((q) => q.x), ys = r.map((q) => q.y);
  const minX = Math.min(...xs), maxX = Math.max(...xs), minY = Math.min(...ys), maxY = Math.max(...ys);
  const size = Math.max(maxX - minX, maxY - minY) || 1;
  r = r.map((q) => ({ x: (q.x - (minX + maxX) / 2) / size, y: (q.y - (minY + maxY) / 2) / size }));
  const cx = r.reduce((a, q) => a + q.x, 0) / r.length, cy = r.reduce((a, q) => a + q.y, 0) / r.length;
  return r.map((q) => ({ x: q.x - cx, y: q.y - cy }));
}

/** The name of the closest shape, or "freeform shape". */
function shapeName(points) {
  const a = normalize(points);
  let best = { name: "freeform shape", score: Infinity };
  for (const [name, shape] of Object.entries(SHAPES)) {
    const b = normalize(shape), score = a.reduce((sum, q, i) => sum + dist(q, b[i]), 0) / a.length;
    if (score < best.score) best = { name, score };
  }
  return best.score < MAX_SCORE ? best.name : "freeform shape";
}

function clearRails() {
  rails.forEach((r) => r.remove());
  rails = [];
}

function startDrawing() {
  if (drawing) return;
  clearRails();
  drawing = true;
  stroke = [{ ...me.position }];
  speak("Drawing.", { interrupt: true });
}

function stopDrawing() {
  if (!drawing) return;
  drawing = false;
  if (stroke.length < 5) {
    stroke = [];
    return speak("Draw a little longer.", { interrupt: true });
  }
  const name = shapeName(stroke);
  rails = [panto.rail(resample(stroke, 8), { strength: 5, name: "Shape path", handles: "me" })];
  stroke = [];
  sound.beep(660, 100, { volume: 0.18 });
  speak(`${name}. Follow the rail.`, { interrupt: true });
}

me.onMove((p) => {
  if (drawing && dist(stroke[stroke.length - 1], p) > 1.5) stroke.push({ x: p.x, y: p.y });
});

voice.intent("start_drawing", { examples: ["start drawing", "begin drawing", "start shape"], interim: false, onMatch: startDrawing });
voice.intent("stop_drawing", { examples: ["stop drawing", "finish drawing", "done drawing", "finish shape"], interim: false, onMatch: stopDrawing });
